import { Component, OnInit } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { Fournisseur } from 'src/app/models/Fournisseur';
import { Medicament } from 'src/app/models/Medicament';
import { FournisseurService } from 'src/app/services/fournisseur.service';

@Component({
  selector: 'app-fournisseur-list',
  templateUrl: './fournisseur-list.component.html',
  styleUrls: ['./fournisseur-list.component.css']
})
export class FournisseurListComponent  implements OnInit {
  fournisseurs: Fournisseur[] = [];
  medicaments: Medicament[] = [];
  selectedFournisseur: Fournisseur | null = null;
  searchTerm: string = '';

  constructor(
    private fournisseurService: FournisseurService,
    private route: ActivatedRoute // Inject ActivatedRoute to access route parameters
  ) { }

  ngOnInit(): void {
    const fournisseurId = this.route.snapshot.paramMap.get('id');

    // Check if we have an ID in the route, and if so, get the specific fournisseur
    if (fournisseurId) {
      this.getMedicamentsByFournisseur(parseInt(fournisseurId, 10));
    } else {
      this.getAllFournisseurs(); // Show all fournisseurs if no specific ID is provided
    }
  }

  // Obtenir tous les fournisseurs
  getAllFournisseurs(): void {
    this.fournisseurService.getAllFournisseurs().subscribe(data => {
      this.fournisseurs = data;
    });
  }

  // Afficher les médicaments d'un fournisseur
  getMedicamentsByFournisseur(idFournisseur: number): void {
    this.fournisseurService.getMedicamentsByFournisseur(idFournisseur).subscribe(data => {
      this.medicaments = data;
      this.selectedFournisseur = this.fournisseurs.find(f => f.idfournisseur === idFournisseur) || null;
    });
  }

  // Recherche des fournisseurs par médicament
  searchFournisseursByMedicament(): void {
    if (this.searchTerm) {
      this.fournisseurService.searchFournisseursByMedicament(this.searchTerm).subscribe(data => {
        this.fournisseurs = data;
      });
    }
  }
}
